const item = $input.first();
const input = item?.json || {};
const customerMessage = String($('Claim Latest Customer Turn').item.json.combined_text || '');
const session = $('Upsert Customer and Session').item.json || {};
const steps = Array.isArray(input.intermediateSteps) ? input.intermediateSteps : [];
const normalizeToolName = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const cancellationStep = steps.find((step) =>
  normalizeToolName(step?.action?.tool).includes('requestcancellationapproval')
);
const draftCancellationStep = steps.find((step) =>
  normalizeToolName(step?.action?.tool) === 'cancelorder'
);

const findCancellationResult = (value, depth = 0) => {
  if (depth > 6 || value === null || value === undefined) return null;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return null;
    try {
      return findCancellationResult(JSON.parse(trimmed), depth + 1);
    } catch {
      return null;
    }
  }
  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = findCancellationResult(entry, depth + 1);
      if (found) return found;
    }
    return null;
  }
  if (typeof value !== 'object') return null;
  if (
    Object.prototype.hasOwnProperty.call(value, 'request_created')
    || Object.prototype.hasOwnProperty.call(value, 'dashboard_request_visible')
    || Object.prototype.hasOwnProperty.call(value, 'request_id')
    || Object.prototype.hasOwnProperty.call(value, 'error')
  ) return value;
  for (const key of ['output', 'data', 'rows', 'result', 'json', 'response']) {
    const found = findCancellationResult(value[key], depth + 1);
    if (found) return found;
  }
  return null;
};

const negativeIntent = /\b(?:do not|don't|dont|never)\s+(?:want\s+to\s+)?cancel\b/i.test(customerMessage)
  || /\bcancel\s+(?:mat|nahi|na)\b/i.test(customerMessage);
const cancellationMessage = !negativeIntent && Boolean(
  /\b(?:cancel|cancellation|cancelled|canceled)\b/i.test(customerMessage)
  || /(?:کینسل|منسوخ)/u.test(customerMessage)
);
const cancellationIntent = Boolean(
  cancellationStep
  || (cancellationMessage
    && !draftCancellationStep
    && (session.order_status !== 'draft' || session.active_order_id))
);
const result = findCancellationResult(cancellationStep?.observation);
const isTrue = (value) => value === true || value === 'true';
const requestCreated = isTrue(result?.request_created);
const dashboardRequestVisible = isTrue(result?.dashboard_request_visible);
const requestId = result?.request_id ?? null;
const orderId = result?.order_id ?? null;
const orderStatus = result?.order_status ?? null;
const errorCode = result?.error ? String(result.error) : null;
const submissionConfirmed = requestCreated
  && dashboardRequestVisible
  && requestId !== null
  && requestId !== ''
  && !errorCode;
const isUrdu = /[؀-ۿ]/u.test(customerMessage);
const isRomanUrdu = !isUrdu && /\b(?:mera|meri|mujhe|karna|karo|kardo|krdo|nahi|nahin|hai)\b/i.test(customerMessage);
const choose = (english, romanUrdu, urdu) => isUrdu ? urdu : (isRomanUrdu ? romanUrdu : english);
const orderLabel = orderId ? ' #' + orderId : '';
const statusLabel = orderStatus ? String(orderStatus).replace(/_/g, ' ') : '';
let output = input.output;

if (cancellationIntent) {
  if (submissionConfirmed) {
    output = choose(
      "I've sent your cancellation request for order" + orderLabel + " to the admin for review. Your order is not cancelled yet.",
      'Order' + orderLabel + ' ki cancellation request admin ko review ke liye bhej di hai. Order abhi cancel nahi hua.',
      'آرڈر' + orderLabel + ' کی منسوخی کی درخواست ایڈمن کو جائزے کے لیے بھیج دی گئی ہے۔ آرڈر ابھی منسوخ نہیں ہوا۔'
    );
  } else if (errorCode === 'multiple_cancellable_orders') {
    const options = Array.isArray(result?.order_options) ? result.order_options : [];
    const ids = options.map((option) => option?.order_id).filter(Boolean);
    const choices = ids.length ? ' Available order numbers: ' + ids.join(', ') + '.' : '';
    output = choose(
      'You have multiple active orders that can be cancelled.' + choices + ' Please tell me the order number you want to cancel.',
      'Aap ke multiple active orders cancel ho sakte hain.' + choices + ' Jis order ko cancel karna hai us ka order number batayein.',
      'آپ کے ایک سے زیادہ فعال آرڈر منسوخ ہو سکتے ہیں۔' + choices + ' براہ کرم مطلوبہ آرڈر نمبر بتائیں۔'
    );
  } else if (errorCode === 'order_not_cancellable') {
    const stage = statusLabel ? ' (' + statusLabel + ')' : '';
